import{_ as r,c as a,o,ag as l}from"./chunks/framework.C86mscM5.js";const c=JSON.parse('{"title":"SSG (Static Site Generation)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/rendering-mode/ssg.md","filePath":"advance/rendering-mode/ssg.md","lastUpdated":1788689791000}'),t={name:"advance/rendering-mode/ssg.md"};function n(i,e,s,h,p,d){return o(),a("div",null,e[0]||(e[0]=[l('<h1 id="ssg-static-site-generation" tabindex="-1">SSG (Static Site Generation) <a class="header-anchor" href="#ssg-static-site-generation" aria-label="Permalink to &quot;SSG (Static Site Generation)&quot;">​</a></h1><blockquote><p>SSG 是 &quot;Static Site Generation&quot;（静态网站生成）的缩写。它表示网页在<strong>构建阶段</strong>被预先渲染成静态的 HTML，然后直接提供给客户端，而不需要服务器实时生成 HTML。</p><p>在传统的 SSR 中，每当用户请求一个页面时，服务器就会实时生成 HTML。有了 SSG，HTML 可以在构建过程中被提前生成，并被托管在 CDN 或其他静态资源服务中。</p><p>与传统的 SSR 相比，SSG 可以提供更快的加载速度以及更少的服务端开销，因为不需要维护一个服务器来实时生成 HTML。然而，SSG 不适合需要动态内容的网站，因为 HTML 是在构建过程中生成的，不支持实时更新。</p></blockquote><h2 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h2><ul><li>首屏渲染更快：用户无需等待 JavaScript 加载和执行，浏览器加载 HTML 后即可看到完整内容，而不是在用户访问时才进行渲染。</li><li>SEO 友好：搜索引擎爬虫可以直接抓取到完整的 HTML 内容。</li><li>易于部署：产物是纯静态文件，无需部署服务器 API，可直接上传到 CDN 或任何静态托管服务。</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><h3 id="image-hosting-service" tabindex="-1">Image hosting service <a class="header-anchor" href="#image-hosting-service" aria-label="Permalink to &quot;Image hosting service&quot;">​</a></h3><ul><li><a href="https://imgkr.com/" target="_blank" rel="nofollow noopener noreferrer">图壳</a></li><li>GitHub + jsdelivr + PicGo</li><li>各大云服务对象存储cos</li></ul><h3 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h3><ul><li><a href="https://disqus.com/" target="_blank" rel="nofollow noopener noreferrer">disqus</a></li></ul><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><ul><li><a href="https://www.algolia.com/" target="_blank" rel="nofollow noopener noreferrer">algolia</a> 非常好用</li><li><a href="https://typesense.org/" target="_blank" rel="nofollow noopener noreferrer">typesense</a></li></ul><h3 id="badge" tabindex="-1">Badge <a class="header-anchor" href="#badge" aria-label="Permalink to &quot;Badge&quot;">​</a></h3><ul><li><a href="https://shields.io/" target="_blank" rel="nofollow noopener noreferrer">badge</a> 一般用于开源项目，统计 star, fork, issues, pull request, release, deploy, visitors</li></ul><h3 id="code-image" tabindex="-1">Code Image <a class="header-anchor" href="#code-image" aria-label="Permalink to &quot;Code Image&quot;">​</a></h3><ul><li><p><a href="https://www.codepng.app/" target="_blank" rel="nofollow noopener noreferrer">https://www.codepng.app/</a></p></li><li><p><a href="https://carbon.now.sh/" target="_blank" rel="nofollow noopener noreferrer">https://carbon.now.sh/</a></p></li><li><p><a href="https://live2d.fghrsh.net/demo/1.4.2/waifu-tips.html" target="_blank" rel="nofollow noopener noreferrer">https://live2d.fghrsh.net/demo/1.4.2/waifu-tips.html</a>)</p></li></ul><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><ul><li>构建时间长：对于大型网站，构建所有页面可能需要较长时间。</li><li>不适合动态内容：如果网站需要频繁更新内容，SSG 可能不适合，因为每次更新都需要重新构建整个网站。</li></ul><h2 id="ssg-框架" tabindex="-1">SSG 框架 <a class="header-anchor" href="#ssg-框架" aria-label="Permalink to &quot;SSG 框架&quot;">​</a></h2><ul><li><a href="https://vuepress.vuejs.org/" target="_blank" rel="nofollow noopener noreferrer">Vuepress</a></li><li><a href="https://vitepress.dev/" target="_blank" rel="nofollow noopener noreferrer">Vitepress</a></li><li><a href="https://rspress.rs/" target="_blank" rel="nofollow noopener noreferrer">Rspress</a></li><li><a href="https://hexo.io/zh-cn/" target="_blank" rel="nofollow noopener noreferrer">Hexo</a></li><li><a href="https://gohugo.io/" target="_blank" rel="nofollow noopener noreferrer">Hugo</a></li><li><a href="https://jekyllrb.com/" target="_blank" rel="nofollow noopener noreferrer">Jekyll</a></li><li><a href="https://astro.build/" target="_blank" rel="nofollow noopener noreferrer">Astro</a></li><li><a href="https://docusaurus.io/" target="_blank" rel="nofollow noopener noreferrer">Docusaurus</a></li><li><a href="https://github.com/gatsbyjs/gatsby" target="_blank" rel="nofollow noopener noreferrer">Gatsby</a></li></ul>',19)]))}const u=r(t,[["render",n]]);export{c as __pageData,u as default};
